private void issueMultiChunkRequest(final long id,PendingRequest pendingRequest){
  Preconditions.checkNotNull(pendingRequest.computation);
  Consumer<ByteString> chunkWriter=new Consumer<ByteString>(){
    private long remaining=pendingRequest.request.getSerializedSize();
    @Override public void accept(    ByteString chunk){
      try {
        StreamingCommitRequestChunk.Builder chunkBuilder=StreamingCommitRequestChunk.newBuilder().setRequestId(id).setSerializedWorkItemCommit(chunk).setComputationId(pendingRequest.computation).setShardingKey(pendingRequest.request.getShardingKey());
        Preconditions.checkState(remaining >= chunk.size());
        remaining-=chunk.size();
        if (remaining > 0) {
          chunkBuilder.setRemainingBytesForWorkItem(remaining);
        }
        StreamingCommitWorkRequest requestChunk=StreamingCommitWorkRequest.newBuilder().addCommitChunk(chunkBuilder).build();
        send(requestChunk);
      } catch (RuntimeException e) {
        LOG.info("Failed to send chunk, request will be retried when stream is reopened.",e);
      }
    }
  }
;
  try (ChunkingByteStream s=new ChunkingByteStream(chunkWriter)){
    pendingRequest.request.writeTo(s);
  }
 catch (  IllegalStateException|IOException e) {
    LOG.info("Stream was broken, request will be retried when stream is reopened.",e);
  }
}
